import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.D7EuCHIT.js";const _=JSON.parse('{"title":"加载、生命周期与安全卸载","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/lifecycle.md","filePath":"plugins/lifecycle.md","lastUpdated":1791895515000}'),r={name:"plugins/lifecycle.md"};function i(c,t,n,l,s,h){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="加载、生命周期与安全卸载" tabindex="-1">加载、生命周期与安全卸载 <a class="header-anchor" href="#加载、生命周期与安全卸载" aria-label="Permalink to &quot;加载、生命周期与安全卸载&quot;">​</a></h1><p>宿主读取有效 manifest，按 capability 选择实现，动态加载 <code>plugin.so</code>，调用导出入口，再执行可选 init/bind。帧边界更新服务，而不是工作线程直接改注册器。</p><table tabindex="0"><thead><tr><th>回调</th><th>用途</th></tr></thead><tbody><tr><td><code>lyra_plugin_init(host,out)</code></td><td>校验 ABI，返回插件描述</td></tr><tr><td><code>init(host)</code></td><td>初始化插件资源；失败拒绝活动实现</td></tr><tr><td><code>bind(host)</code></td><td>绑定上下文与模块接口</td></tr><tr><td><code>on_frame(host,time_ns)</code></td><td>服务被根路由调用时执行</td></tr><tr><td><code>on_input(host,input)</code></td><td>处理命中输入，1 表示消费</td></tr><tr><td><code>query_interface(...)</code></td><td>发布可选接口，缺失返回 NULL</td></tr><tr><td><code>shutdown(host)</code></td><td>终止线程、撤销回调、释放持有资源</td></tr></tbody></table><p>不要假定私有注册器实现细节，不假定 on_frame 每个显示刷新都无条件执行。需要继续动画时调用 request_frame。</p><h2 id="接口寿命" tabindex="-1">接口寿命 <a class="header-anchor" href="#接口寿命" aria-label="Permalink to &quot;接口寿命&quot;">​</a></h2><p>接口表及其 user 在所属模块存续期间有效。不要缓存外部提供者接口跨卸载，也不要从工作线程调用查找/注册。公开值快照可以复制留存；任何指针都必须按对应 lifetime 管理。</p><p>动态库卸载前必须不存在执行库代码的线程或回调。播放 provider 的 quiesce 失败时保留旧提供者和库，不能为了 UI 显示“卸载成功”强行 dlclose。插件的其他线程也必须由 shutdown 结束。</p><h2 id="配置与目录卸载" tabindex="-1">配置与目录卸载 <a class="header-anchor" href="#配置与目录卸载" aria-label="Permalink to &quot;配置与目录卸载&quot;">​</a></h2><p>样式/schema/modes 描述由宿主复制或依所有者保存；移除所有者恢复内置描述。用户保存的配置和模式 ID 不随卸载删除。模式提供者缺失时实际使用安全回退，重新安装后可恢复保存的 ID。</p><h2 id="多包竞争" tabindex="-1">多包竞争 <a class="header-anchor" href="#多包竞争" aria-label="Permalink to &quot;多包竞争&quot;">​</a></h2><p>当前注册器优先外部根，再内部根；同 capability 内还有确定性 ID 排序。该行为只是当前实现，不应成为跨插件编排协议。外部列表保留发现的有效但未启用包；“存在”不等于“活动”。避免同一设备安装多个都想接管 playback 的包而期待它们串联。</p><p>下一步：<a href="/LyraPlayer-docs-site/plugins/manifest">清单与元数据</a>。</p>',12)])])}const u=e(r,[["render",i]]);export{_ as __pageData,u as default};
